/// Octave's interp1(x, y, xi, 'nearest') over a table of nodes (no extrapolation: nan outside [x(1), x(n)]); the breaks
/// are the midpoints, a tie going to the upper node.
/// - to_ap: bool (passed true or false)
/// - xi: real[1] (passed a plain number)
/// - returns y: real[1] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn kp_ap_nearest(to_ap: bool, xi: f64) -> f64 {
    let mut y: f64 = 0.0;
    let mut n: i64 = 28;
    let mut x0: f64 = (if to_ap { crate::gen::kpap::DATA_KP_AP_KP[0] } else { crate::gen::kpap::DATA_KP_AP_AP[0] });
    let mut xn: f64 = (if to_ap { crate::gen::kpap::DATA_KP_AP_KP[((n - 1)) as usize] } else { crate::gen::kpap::DATA_KP_AP_AP[((n - 1)) as usize] });
    if (!((xi >= x0) && (xi <= xn))) {
        y = f64::NAN;
    } else {
        let mut k: i64 = 0;
        let mut stop: bool = false;
        {
            let __end125: i64 = (n - 1);
            let mut i: i64 = 0;
            while i < __end125 {
                let mut a: f64 = (if to_ap { crate::gen::kpap::DATA_KP_AP_KP[(i) as usize] } else { crate::gen::kpap::DATA_KP_AP_AP[(i) as usize] });
                let mut b: f64 = (if to_ap { crate::gen::kpap::DATA_KP_AP_KP[((i + 1)) as usize] } else { crate::gen::kpap::DATA_KP_AP_AP[((i + 1)) as usize] });
                if (!stop) {
                    if (((a + b) / 2.0) <= xi) {
                        k = (i + 1);
                    } else {
                        stop = true;
                    }
                }
                i += 1;
            }
        }
        k = rt::imin(k, (n - 1));
        y = (if to_ap { crate::gen::kpap::DATA_KP_AP_AP[(k) as usize] } else { crate::gen::kpap::DATA_KP_AP_KP[(k) as usize] });
    }
    y
}

/// kp2ap (atmos.spaceweather): the nearest node of the standard table, Kp clamped to [0, 9].
/// - kp: real[1] (passed a plain number)
/// - returns ap: real[1] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn kp2ap(kp: f64) -> f64 {
    let mut ap: f64 = 0.0;
    if (kp).is_nan() {
        ap = f64::NAN;
    } else {
        ap = crate::gen::swindex::kp_ap_nearest(true, rt::fmax(rt::fmin(kp, 9.0), 0.0));
    }
    ap
}

/// ap2kp (atmos.spaceweather): the nearest node, ap clamped to [0, 400].
/// - ap: real[1] (passed a plain number)
/// - returns kp: real[1] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn ap2kp(ap: f64) -> f64 {
    let mut kp: f64 = 0.0;
    if (ap).is_nan() {
        kp = f64::NAN;
    } else {
        kp = crate::gen::swindex::kp_ap_nearest(false, rt::fmax(rt::fmin(ap, 400.0), 0.0));
    }
    kp
}

/// ap2kp of data.spaceweather_forecast: linear with extrapolation on Kp = (0:27)/3 over the table's ap, ap clamped
/// above at 400 only (Octave's min ignores a nan, so a nan ap is 400).
/// - ap: real[1] (passed a plain number)
/// - returns kp: real[1] (passed a plain number)
#[allow(clippy::too_many_arguments)]
pub fn ap2kp_forecast(ap: f64) -> f64 {
    let mut kp: f64 = 0.0;
    let mut n: i64 = 28;
    let mut xi: f64 = (if (ap).is_nan() { 400.0 } else { rt::fmin(ap, 400.0) });
    let mut lo: i64 = 0;
    let mut hi: i64 = n;
    {
        let __n127: i64 = 16;
        let mut __k126: i64 = 0;
        loop {
            let mut mid: i64 = ((lo + hi) / 2);
            if (crate::gen::kpap::DATA_KP_AP_AP[(mid) as usize] <= xi) {
                lo = (mid + 1);
            } else {
                hi = mid;
            }
            __k126 += 1;
            if (lo >= hi) { break; }
            if __k126 >= __n127 {
                break;
            }
        }
    }
    let mut i: i64 = 0;
    if (lo > 0) {
        i = (lo - 1);
    }
    i = rt::imin(i, (n - 2));
    let mut slope: f64 = (((((i + 1) as f64) / 3.0) - ((i as f64) / 3.0)) / (crate::gen::kpap::DATA_KP_AP_AP[((i + 1)) as usize] - crate::gen::kpap::DATA_KP_AP_AP[(i) as usize]));
    kp = ((slope * (xi - crate::gen::kpap::DATA_KP_AP_AP[(i) as usize])) + ((i as f64) / 3.0));
    kp
}

