/// data.drivers: the index set a density model takes.
/// - model: AtmosModel (passed a choice, as its option's number)
/// - returns d: DriverSet (passed a choice, as its option's number)
#[allow(clippy::too_many_arguments)]
pub fn drivers_for(model: i64) -> i64 {
    let mut d: i64 = 0;
    if (model == crate::gen::densitymodel::ATMOSMODEL_EXPONENTIAL) {
        d = crate::gen::swindex::DRIVERSET_NO_DRIVERS;
    } else if ((model == crate::gen::densitymodel::ATMOSMODEL_NRLMSISE) || (model == crate::gen::densitymodel::ATMOSMODEL_DTM2020)) {
        d = crate::gen::swindex::DRIVERSET_F107_KP;
    } else if (model == crate::gen::densitymodel::ATMOSMODEL_DTM2020_RESEARCH) {
        d = crate::gen::swindex::DRIVERSET_F30_AP60;
    } else {
        d = crate::gen::swindex::DRIVERSET_SET_INDICES;
    }
    d
}
